public static async Task<IReadOnlyList<BlogViews>> GetViewsByBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogPosts
        select new BlogViews
        {
            BlogId = blogPosts.Key,
            TotalViews = blogPosts.Sum(post => post.Views)
        };

    var results = await query.ToListAsync(cancellationToken);
    return results;
}

public sealed class BlogViews
{
    public int BlogId { get; set; }
    public int TotalViews { get; set; }
}
